{
  "verses": [
    {
      "chapter": 7,
      "text_ar": "وقام باروخ وخرج من القبر ووجد النسر جالساً خارج القبر.",
      "verse": 1
    },
    {
      "chapter": 7,
      "text_ar": "وقال له النسر بصوت بشري: \"السلام لك يا باروخ، يا وكيل الأمانة.\"",
      "verse": 2
    },
    {
      "chapter": 7,
      "text_ar": "وقال له باروخ: \"أنت الذي تتكلم مختار من بين كل طيور السماء، لأن هذا واضح من بريق عينيك، أخبرني إذن، ماذا تفعل هنا؟\"",
      "verse": 3
    },
    {
      "chapter": 7,
      "text_ar": "وقال له النسر: \"أُرسلت إلى هنا لكي تستخدموني في إرسال أي رسالة تريدها.\"",
      "verse": 4
    },
    {
      "chapter": 7,
      "text_ar": "وقال له باروخ: \"أبإمكانك حمل هذه الرسالة إلى إرميا في بابل؟\"",
      "verse": 5
    }
  ],
  "book_code": "4BAR"
}
